sql_query:
SELECT "Control regimen"
FROM clinical_trials
WHERE "Cancer type" = 'Breast' AND "Control arm" = 'Chemo' AND "Name of ICI" = 'Durvalumab' AND "Trial phase" = 'Phase 2';

ground_truth_sql:
WITH base AS (
SELECT "NCT", "PubMed ID", "Trial name", "Control regimen" AS source_value FROM clinical_trials WHERE "Cancer type" = 'Breast' AND "Control arm" = 'Chemo' AND "Name of ICI" = 'Durvalumab' AND "Trial phase" = 'Phase 2'
)
SELECT "NCT", "PubMed ID", "Trial name", source_value, derive_control_drugs(source_value) AS "control_drugs"
FROM base;
